using System.Security.Cryptography;
using Jindan.Contracts;
using Jindan.Core;
using static Jindan.Core.DomainRules;
namespace Jindan.Infrastructure;

public sealed partial class LocalWorkspace
{
    public Task<AssetInfo?> ResolveProjectAssetAsync(Identity actor, DocumentContext context, string storedPath, CancellationToken ct = default) => Locked<AssetInfo?>(() => { var user = Actor(actor); Require(context.UserId == user.Id, "UNAUTHENTICATED", "The document user is not this authenticated session."); Require(context.ProjectId is not null, "PROJECT_SCOPE", "Select a project."); AssetAccess(user, context.ProjectId!); Require(Path.IsPathFullyQualified(storedPath) && !storedPath.StartsWith("\\\\", StringComparison.Ordinal), "ASSET_PATH", "Use a local source path."); var path = Path.GetFullPath(storedPath); var asset = _state.Assets.FirstOrDefault(a => a.ProjectId == context.ProjectId && string.Equals(Blob(a.Sha256), path, StringComparison.OrdinalIgnoreCase)); if (asset is null) return null; var blob = Blob(asset.Sha256); Require(File.Exists(blob) && new FileInfo(blob).Length == asset.Size && FileHash(blob) == asset.Sha256, "CORRUPT_ASSET", "The existing project asset differs from its original hash."); return Info(asset); }, ct);
    string Blob(string hash) { Require(hash.Length == 64 && hash.All(c => char.IsAsciiHexDigit(c)) && hash == hash.ToLowerInvariant(), "CORRUPT_ASSET", "Asset hash is invalid."); CheckNoLinks(_assets); var blob = Path.Combine(_assets, hash + ".blob"); if (File.Exists(blob)) Require((File.GetAttributes(blob) & FileAttributes.ReparsePoint) == 0, "PATH", "Linked assets are not allowed."); return blob; }
    void AssetAccess(StoredUser user, string projectId, bool write = false) { Require(_state.Records.Any(r => IsProject(r.Kind) && r.Id == projectId && !r.Deleted), "PROJECT_SCOPE", "Asset parent project is unavailable."); Require(user.Role == "admin" || user.ProjectIds.Contains(projectId), "FORBIDDEN", "The asset is outside the assigned project."); if (write) Require(user.Role is "admin" or "editor", "FORBIDDEN", "The user cannot import assets."); }
    AssetInfo Info(StoredAsset asset) => new(asset.Id, asset.Sha256, asset.OriginalName, asset.Size, asset.MediaType, Blob(asset.Sha256));
    static string FileHash(string path) { using var s = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read); return Convert.ToHexStringLower(SHA256.HashData(s)); }
    static void CopyFile(string source, string target, CancellationToken ct) { using var input = new FileStream(source, FileMode.Open, FileAccess.Read, FileShare.Read); Require(input.Length <= 256L * 1024 * 1024, "ASSET_LIMIT", "Assets are limited to256MiB."); using var output = new FileStream(target, FileMode.CreateNew, FileAccess.Write, FileShare.None); var buffer = new byte[128 * 1024]; int read; while ((read = input.Read(buffer)) > 0) { ct.ThrowIfCancellationRequested(); output.Write(buffer, 0, read); } output.Flush(true); ct.ThrowIfCancellationRequested(); }
    public Task<AssetInfo> ImportAsync(Identity actor, string projectId, string sourcePath, CancellationToken ct = default) => Locked(() => { var user = Actor(actor); AssetAccess(user, projectId, true); Require(Path.IsPathFullyQualified(sourcePath) && File.Exists(sourcePath), "ASSET_PATH", "Select an existing local asset."); CheckNoLinks(Path.GetDirectoryName(Path.GetFullPath(sourcePath))!); Require((File.GetAttributes(sourcePath) & FileAttributes.ReparsePoint) == 0, "ASSET_PATH", "Asset links are not imported."); CheckNoLinks(_assets); var temp = Path.Combine(_assets, ".import-" + Guid.NewGuid().ToString("N")); try { CopyFile(sourcePath, temp, ct); var hash = FileHash(temp); var existing = _state.Assets.FirstOrDefault(a => a.ProjectId == projectId && a.Sha256 == hash); if (existing is not null) { Require(File.Exists(Blob(hash)) && FileHash(Blob(hash)) == hash, "CORRUPT_ASSET", "Stored original asset differs from its content hash."); return Info(existing); } var blob = Blob(hash); if (File.Exists(blob)) Require(FileHash(blob) == hash, "CORRUPT_ASSET", "Stored original asset differs from its content hash."); else File.Move(temp, blob); var asset = new StoredAsset { Id = Guid.NewGuid().ToString("N"), ProjectId = projectId, OwnerId = user.Id, Sha256 = hash, OriginalName = Path.GetFileName(sourcePath), Size = new FileInfo(blob).Length, MediaType = Media(sourcePath) }; var next = Clone(); next.Assets.Add(asset); Commit(next, ct); return Info(asset); } catch (IOException) { throw new WorkspaceException("ASSET_IO", "The local asset is locked, unavailable, or could not be stored."); } finally { if (File.Exists(temp)) File.Delete(temp); } }, ct);
    public Task<AssetInfo> GetAsync(Identity actor, string id, CancellationToken ct = default) => Locked(() => { var user = Actor(actor); var asset = _state.Assets.SingleOrDefault(a => a.Id == id); Require(asset is not null, "NOT_FOUND", "Asset not found."); AssetAccess(user, asset!.ProjectId); Require(File.Exists(Blob(asset.Sha256)) && new FileInfo(Blob(asset.Sha256)).Length == asset.Size && FileHash(Blob(asset.Sha256)) == asset.Sha256, "CORRUPT_ASSET", "Stored original asset differs from its content hash."); return Info(asset); }, ct);
    public async Task ExportAsync(Identity actor, string id, string destination, CancellationToken ct = default) { await Locked(() => { var user = Actor(actor); var asset = _state.Assets.SingleOrDefault(a => a.Id == id); Require(asset is not null, "NOT_FOUND", "Asset not found."); AssetAccess(user, asset!.ProjectId); var source = Blob(asset.Sha256); Require(FileHash(source) == asset.Sha256, "CORRUPT_ASSET", "Stored original asset differs from its hash."); Destination(destination); var temp = Path.Combine(Path.GetDirectoryName(Path.GetFullPath(destination))!, ".asset-export-" + Guid.NewGuid().ToString("N")); try { CopyFile(source, temp, ct); Destination(destination); File.Move(temp, destination, false); } finally { if (File.Exists(temp)) File.Delete(temp); } return true; }, ct); }
    static string Media(string path) => Path.GetExtension(path).ToLowerInvariant() switch { ".png" => "image/png", ".jpg" or ".jpeg" => "image/jpeg", ".gif" => "image/gif", ".pdf" => "application/pdf", ".hwpx" => "application/vnd.hancom.hwpx", _ => "application/octet-stream" };
}
